/// Strict readers for the Mercenary III documents.
///
/// Every MIII document is machine-generated by `research/mercenary-iii-st/`, so a
/// missing or mistyped field is a broken export, never a value to default. A failure
/// names the path it was found at.

export class DionDocumentError extends Error {
  override readonly name = 'DionDocumentError';
}

export const fail = (message: string): never => {
  throw new DionDocumentError(message);
};

export const record = (
  value: unknown,
  path: string
): Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : fail(`${path} is not a record`);

export const list = (value: unknown, path: string): readonly unknown[] =>
  Array.isArray(value) ? value : fail(`${path} is not a list`);

export const text = (value: unknown, path: string): string =>
  typeof value === 'string' ? value : fail(`${path} is not text`);

export const int = (
  value: unknown,
  path: string,
  min = -0x8000_0000,
  max = 0x7fff_ffff
): number =>
  Number.isInteger(value) &&
  (value as number) >= min &&
  (value as number) <= max
    ? (value as number)
    : fail(`${path} is not an integer from ${min} to ${max}`);

export const byte = (value: unknown, path: string): number =>
  int(value, path, 0, 0xff);

export const word = (value: unknown, path: string): number =>
  int(value, path, 0, 0xffff);

export const sword = (value: unknown, path: string): number =>
  int(value, path, -0x8000, 0x7fff);

export const bool = (value: unknown, path: string): boolean =>
  typeof value === 'boolean' ? value : fail(`${path} is not a boolean`);

export const ints = (
  value: unknown,
  path: string,
  length?: number,
  min?: number,
  max?: number
): number[] => {
  const items = list(value, path);
  if (length !== undefined && items.length !== length) {
    fail(`${path} should hold ${length} values, and holds ${items.length}`);
  }
  return items.map((item, index) => int(item, `${path}[${index}]`, min, max));
};

export const pair = (value: unknown, path: string): [number, number] => {
  const [a, b] = ints(value, path, 2);
  return [a!, b!];
};

export const triple = (
  value: unknown,
  path: string
): [number, number, number] => {
  const [a, b, c] = ints(value, path, 3);
  return [a!, b!, c!];
};

export const optional = <T>(
  value: unknown,
  read: (value: unknown) => T
): T | undefined => (value === undefined ? undefined : read(value));

export const nullable = <T>(
  value: unknown,
  read: (value: unknown) => T
): T | null => (value === null ? null : read(value));

/// A `$`-prefixed hexadecimal address, as every MIII document writes one.
export const address = (value: unknown, path: string): number => {
  const raw = text(value, path);
  return /^\$[\dA-F]{1,6}$/.test(raw)
    ? Number.parseInt(raw.slice(1), 16)
    : fail(`${path} is not a $-address`);
};

/// Research Provenance: the half-open source range and its SHA-256.
export interface Provenance {
  readonly range: readonly [number, number];
  readonly sha256: string;
}

export const provenance = (value: unknown, path: string): Provenance => {
  const raw = record(value, path);
  const range = list(raw['range'], `${path}.range`);
  if (range.length !== 2) {
    fail(`${path}.range should be a pair`);
  }
  const lo = address(range[0], `${path}.range[0]`);
  const hi = address(range[1], `${path}.range[1]`);
  if (hi <= lo) {
    fail(`${path}.range is empty`);
  }
  const sha256 = text(raw['sha256'], `${path}.sha256`);
  if (!/^[\da-f]{64}$/.test(sha256)) {
    fail(`${path}.sha256 is not a SHA-256`);
  }
  return { range: [lo, hi], sha256 };
};

/// Entries of a JSON object keyed by decimal integers, read with `read`.
export const keyed = <T>(
  value: unknown,
  path: string,
  read: (value: unknown, path: string, key: number) => T
): ReadonlyMap<number, T> => {
  const raw = record(value, path);
  const result = new Map<number, T>();
  for (const [key, item] of Object.entries(raw)) {
    if (!/^\d+$/.test(key)) {
      fail(`${path} key ${key} is not a decimal integer`);
    }
    const index = Number(key);
    result.set(index, read(item, `${path}.${key}`, index));
  }
  return result;
};
